def validate(data,s,path='root'):
 typ=s.get('type');assert typ is None or {'object':isinstance(data,dict),'array':isinstance(data,list),'string':isinstance(data,str),'integer':isinstance(data,int),'number':isinstance(data,(int,float))}[typ],path
 if 'enum' in s:assert data in s['enum'],path
 if isinstance(data,dict):
  for k in s.get('required',[]):assert k in data,path+'.'+k
  if s.get('additionalProperties') is False:assert not set(data)-set(s.get('properties',{})),path
  for k,v in data.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 if isinstance(data,list):
  assert len(data)>=s.get('minItems',0),path
  for i,v in enumerate(data):validate(v,s.get('items',{}),path+f'[{i}]')
 if isinstance(data,str):assert len(data)>=s.get('minLength',0),path
 if isinstance(data,(int,float)):
  assert data>=s.get('minimum',float('-inf')) and data<=s.get('maximum',float('inf')),path
